    "recipe_fr": "<p>Coupez les pommes de terre en frites, arrosez-les d'huile et enfournez-les à 220 °C jusqu'à ce qu'elles soient croustillantes ; rincez les moules et jetez celles qui sont abîmées ; faites revenir les échalotes, le poireau et le céleri, ajoutez le vin et portez à ébullition ; ajoutez les moules, couvrez et laissez mijoter 5 minutes, puis parsemez de persil.</p>",
