    "name_fr": "Tostada de ceviche de Lima avec patate douce, avocat et œuf",
    "base_fr": "Brunch côtier péruvien",
    "ingredients_fr": "220 g poisson blanc || 3 citrons verts || 4 tostadas de maïs || 1 patate douce || 1 avocat || 2 oeufs || 1/4 oignon rouge || 2 c. à soupe coriandre || 1 piment",
    "recipe_fr": "<p>Faites mariner brièvement le poisson dans du jus de citron vert avec de l'oignon et du piment.</p><p>Faites cuire la patate douce et l'œuf.</p><p>Disposez-les sur une tostada avec de l'avocat, de la patate douce, du ceviche, de l'œuf et de la coriandre.</p>",
    "difficulty_fr": "Facile",
    "country_fr": "Pérou",
