    "description_ru": "Хрустящая тостада с севиче из лайма, сладким картофелем, авокадо, кинзой и яйцом всмятку.",
    "name_ru": "Тостада с севиче из Лимы, сладким картофелем, авокадо и яйцом.",
    "base_ru": "Перуанский прибрежный бранч",
