    "recipe_ru": "<p>Кратковременно замаринуйте рыбу в лайме с луком и чили.</p><p>Отварите сладкий картофель и яйцо.</p><p>Выложите на тостаду вместе с авокадо, сладким картофелем, севиче, яйцом и кинзой.</p>",
    "difficulty_ru": "Легко",
