    "ingredients": "160 г басмати ориз || 180 г пушена бяла риба || 2 яйца || 80 г грах || 1 ч.л. къри прах || 25 г масло || 1 с.л. магданоз || 1 с.л. кориандър || 1 лимон",
    "recipe": "<p>Свари ориза рохко.</p><p>Загрей масло с къри прах, добави грах и пушена риба.</p><p>Смеси с ориза, добави меко яйце, лимон и много билки.</p>",
