    "recipe_de": "<p>Den Reis weichkochen.</p><p>Öl mit Currypulver erhitzen, Erbsen und Räucherfisch hinzufügen.</p><p>Mit dem Reis vermengen, weichgekochtes Ei, Zitrone und reichlich Kräuter dazugeben.</p>",
