    "base_es": "brunch colonial británico",
    "ingredients_es": "160 g arroz basmati || 180 g pescado blanco ahumado || 2 huevos || 80 g guisantes || 1 cdta curry en polvo || 25 g mantequilla || 1 cda perejil || 1 cda cilantro || 1 limón",
    "recipe_es": "<p>Cueza el arroz hasta que esté tierno.</p><p>Caliente el aceite con el curry en polvo, añada los guisantes y el pescado ahumado.</p><p>Mezcle con el arroz, agregue el huevo pasado por agua, el limón y muchas hierbas aromáticas.</p>",
