    "ingredients_fr": "160 g riz basmati || 180 g poisson blanc fumé || 2 oeufs || 80 g petits pois || 1 c. à café curry en poudre || 25 g beurre || 1 c. à soupe persil || 1 c. à soupe coriandre || 1 citron",
    "recipe_fr": "<p>Faites cuire le riz jusqu'à ce qu'il soit tendre.</p><p>Faites chauffer l'huile avec le curry, ajoutez les petits pois et le poisson fumé.</p><p>Mélangez avec le riz, puis ajoutez l'œuf mollet, le citron et une généreuse quantité d'herbes aromatiques.</p>",
