    "recipe_ru": "<p>Отварите рис до мягкости.</p><p>Разогрейте масло с порошком карри, добавьте горошек и копченую рыбу.</p><p>Смешайте с рисом, добавьте яйцо всмятку, лимон и много зелени.</p>",
