    "image": "https://drive.google.com/file/d/1g3nXOAPwZbn5FvgTvTcos1l5guwA0aUl/view?usp=drivesdk",
    "description": "Кремообразен царевичен грис с пикантни скариди, пушен пипер, зелен лук и поширано яйце.",
    "ingredients": "120 г царевичен грис || 260 мл вода или бульон || 220 г скариди || 25 г масло || 60 г чедър || 2 стръка зелен лук || 1 ч.л. пушен пипер || 1 скилидка чесън || 2 яйца || 1/2 лимон",
    "recipe": "<p>Свари грица кремообразно и разбъркай масло и чедър.</p><p>Запържи скаридите с чесън и пушен пипер.</p><p>Поширай яйце и подреди всичко с лимон и зелен лук.</p>",
    "time": 36,
    "difficulty": "Средно",
