    "ingredients": "2 филии квасен хляб || 180 г обезсолена бакаляу || 2 яйца || 1 печен червен пипер || 40 г маслини || 1 картоф || 2 с.л. зехтин || 1 лимон || 2 с.л. магданоз",
    "recipe": "<p>Свари картофа и бакаляу, после намачкай с малко зехтин и лимон.</p><p>Запечи хляба, намажи крема, добави печен пипер и рохко яйце.</p><p>Завърши с маслини и магданоз.</p>",
    "time": 32,
