    "description_en": "Crispy toast with cod cream, roasted pepper, soft-boiled egg, olives and lemon.",
    "name_en": "Lisbon toast with cod, egg and roasted pepper",
    "base_en": "Portuguese coastal brunch",
    "ingredients_en": "2 slices sourdough bread || 180 g desalted bacalhau || 2 eggs || 1 roasted red pepper || 40 g olives || 1 potato || 2 tbsp olive oil || 1 lemon || 2 tbsp parsley",
    "recipe_en": "<p>Boil the potatoes and cod, then mash with a little olive oil and lemon.</p><p>Toast the bread, spread the cream, add roasted pepper and a soft-boiled egg.</p><p>Finish with olives and parsley.</p>",
