    "ingredients_es": "600 g de calamares limpios || 1 cebolla || 1 zanahoria || 1 calabacín || 2 cucharadas de gochujang || 1 cucharada de salsa de soja || 1 cucharadita de aceite de sésamo || 2 cebolletas",
    "recipe_es": "<p>Abre el calamar en trozos grandes y planos y hazle cortes superficiales en forma de rombo; mezcla el gochujang, la salsa de soja y el aceite de sésamo y cubre el calamar y las verduras troceadas; ásalo directamente sobre una parrilla muy caliente durante 2 o 3 minutos por cada lado hasta que los bordes estén ahumados; córtalo en rodajas y sírvelo con cebolleta y la salsa picante restante.</p>",
