    "country_es": "Corea",
    "tag_es": "Calamares a la parrilla al estilo coreano",
    "description_fr": "Une authentique recette coréenne de fruits de mer pour quatre personnes, avec des quantités pratiques et une saveur équilibrée.",
    "name_fr": "Calamars grillés épicés coréens",
    "base_fr": "Calamars grillés coréens",
    "ingredients_fr": "600 g de calamars nettoyés || 1 oignon || 1 carotte || 1 courgette || 2 cuillères à soupe de gochujang || 1 cuillère à soupe de sauce soja || 1 cuillère à café d’huile de sésame || 2 oignons nouveaux",
    "recipe_fr": "<p>Ouvrez les calamars en larges morceaux plats et incisez-les légèrement en losanges.</p><p>Mélangez le gochujang, la sauce soja et l'huile de sésame, puis enrobez les calamars et les légumes coupés en morceaux de ce mélange.</p><p>Faites griller directement sur une grille très chaude pendant 2 à 3 minutes de chaque côté, jusqu'à ce que les bords soient fumants.</p><p>Tranchez et servez avec des oignons nouveaux et le reste de la sauce piquante.</p>",
    "difficulty_fr": "Facile",
    "country_fr": "Corée",
    "tag_fr": "Calamars grillés coréens",
    "description_ru": "Аутентичный корейский рецепт морепродуктов на четверых, с удобными пропорциями и сбалансированным вкусом.",
    "name_ru": "корейские острые кальмары на гриле",
    "base_ru": "корейские кальмары на гриле",
    "ingredients_ru": "600 г очищенных кальмаров || 1 луковица || 1 морковь || 1 кабачок || 2 ст. л. пасты кочуджан || 1 ст. л. соевого соуса || 1 ч. л. кунжутного масла || 2 зеленых лука",
    "recipe_ru": "<p>Разделите кальмара на крупные плоские куски и сделайте легкие надрезы в виде ромбов; смешайте кочуджан, соевый соус и кунжутное масло и обмажьте этой смесью кальмара и нарезанные овощи; жарьте на гриле прямо над очень горячей решеткой по 2-3 минуты с каждой стороны до появления дымка по краям; нарежьте и подавайте с зеленым луком и оставшимся острым соусом.</p>",
    "difficulty_ru": "Легко",
