    "ingredients": "600 г големи сурови скариди || 2 лимона || 3 скилидки чесън || 2 ч.л. сушен риган || 60 мл зехтин || 150 г фета || 2 червени чушки || 1 ч.л. сол",
    "recipe": "<p>Обели скаридите, като оставиш опашките, и ги мариновай с лимон, чесън, риган и зехтин за 20 минути</p><p>Нанижи скаридите и парчета чушка на метални или накиснати дървени шишове</p><p>Печи директно върху силно загрята решетка по 2–3 минути от страна до розово месо и леки следи от жарта</p><p>Поднеси веднага с натрошена фета, лимон и още риган</p>",
    "time": 30,
