    "base_en": "Greek grilled prawns",
    "ingredients_en": "600 g large raw prawns || 2 lemons || 3 garlic cloves || 2 tsp dried oregano || 60 ml olive oil || 150 g feta || 2 red peppers || 1 tsp salt",
    "recipe_en": "<p>Peel the prawns, leaving the tails on, and marinate with lemon, garlic, oregano and olive oil for 20 minutes</p><p>Thread prawns and pepper pieces onto metal or soaked wooden skewers</p><p>Grill directly over a very hot grate for 2 to 3 minutes per side until pink with light char marks</p><p>Serve immediately with crumbled feta, lemon and extra oregano</p>",
    "difficulty_en": "Medium",
    "country_en": "Greece",
    "tag_en": "Greek grilled prawns",
    "description_de": "Ein sorgfältig erprobtes griechisches Tavernenrezept für vier Personen mit praktischen Mengenangaben und klarer Zubereitungstechnik.",
    "name_de": "Griechische gegrillte Garnelenspieße mit Zitrone, Oregano und Feta",
    "base_de": "Griechische Grillgarnelen",
    "ingredients_de": "600 g große rohe Garnelen || 2 Zitronen || 3 Knoblauchzehen || 2 TL getrockneter Oregano || 60 ml Olivenöl || 150 g Feta || 2 rote Paprika || 1 TL Salz",
    "recipe_de": "<p>Die Garnelen schälen, die Schwänze dranlassen und 20 Minuten mit Zitrone, Knoblauch, Oregano und Olivenöl marinieren</p><p>Garnelen und Paprikastücke auf Metall- oder eingeweichte Holzspieße stecken</p><p>Direkt über einem sehr heißen Grillrost 2 bis 3 Minuten pro Seite grillen, bis sie rosa sind und leichte Grillstreifen haben</p><p>Sofort mit zerbröckeltem Feta, Zitrone und zusätzlichem Oregano servieren.</p>",
