    "name_es": "Brochetas griegas de gambas a la parrilla con limón, orégano y queso feta.",
    "base_es": "Langostinos griegos a la parrilla",
    "ingredients_es": "600 g de langostinos grandes crudos || 2 limones || 3 dientes de ajo || 2 cucharaditas de orégano seco || 60 ml de aceite de oliva || 150 g de queso feta || 2 pimientos rojos || 1 cucharadita de sal",
    "recipe_es": "<p>Pele las gambas, dejando las colas, y marínelas con limón, ajo, orégano y aceite de oliva durante 20 minutos; ensarte las gambas y los trozos de pimiento en brochetas de metal o de madera previamente remojadas; áselas directamente sobre una parrilla muy caliente durante 2 o 3 minutos por cada lado, hasta que estén rosadas con ligeras marcas de la parrilla; sírvalas inmediatamente con queso feta desmenuzado, limón y orégano adicional.</p>",
    "difficulty_es": "Media",
    "country_es": "Grecia",
    "tag_es": "Langostinos griegos a la parrilla",
    "description_fr": "Une recette de taverne grecque soigneusement testée pour quatre personnes, avec des quantités pratiques et une technique claire.",
    "name_fr": "Brochettes de crevettes grillées à la grecque, au citron, à l'origan et à la feta",
    "base_fr": "crevettes grillées à la grecque",
    "ingredients_fr": "600 g de grosses crevettes crues || 2 citrons || 3 gousses d’ail || 2 c. à café d’origan séché || 60 ml d’huile d’olive || 150 g de feta || 2 poivrons rouges || 1 c. à café de sel",
    "recipe_fr": "<p>Décortiquez les crevettes en conservant les queues et faites-les mariner 20 minutes avec du citron, de l'ail, de l'origan et de l'huile d'olive.</p><p>Enfilez les crevettes et les morceaux de poivron sur des brochettes en métal ou en bois préalablement trempées.</p><p>Faites-les griller directement sur une grille très chaude 2 à 3 minutes de chaque côté, jusqu'à ce qu'elles soient roses et légèrement marquées.</p><p>Servez immédiatement avec de la feta émiettée, du citron et de l'origan frais.</p>",
    "difficulty_fr": "Moyen",
    "country_fr": "Grèce",
    "tag_fr": "crevettes grillées à la grecque",
    "description_ru": "Тщательно проверенный рецепт греческого блюда из таверны на четверых, с указанием практических пропорций и понятной техникой приготовления.",
    "name_ru": "Греческие шашлычки из креветок на гриле с лимоном, орегано и фетой.",
    "base_ru": "Греческие креветки на гриле",
    "ingredients_ru": "600 г крупных сырых креветок || 2 лимона || 3 зубчика чеснока || 2 ч. л. сушеного орегано || 60 мл оливкового масла || 150 г феты || 2 красных перца || 1 ч. л. соли",
    "recipe_ru": "<p>Очистите креветки, оставив хвостики, и замаринуйте их в лимоне, чесноке, орегано и оливковом масле на 20 минут; нанижите креветки и кусочки перца на металлические или предварительно замоченные деревянные шампуры; жарьте на гриле прямо над очень горячей решеткой по 2-3 минуты с каждой стороны до образования розового цвета с легкими поджаристыми полосками; подавайте немедленно с раскрошенной фетой, лимоном и дополнительным орегано.</p>",
