    "ingredients_de": "1,2 kg geputzter Oktopus || 2 Lorbeerblätter || 80 ml Rotweinessig || 60 ml Olivenöl || 2 Zitronen || 2 TL getrockneter Oregano || 3 Knoblauchzehen || 20 g Petersilie",
