    "recipe_es": "<p>Cocine a fuego lento el pulpo con laurel hasta que esté tierno; escúrralo, déjelo enfriar y separe los tentáculos; áselo a la parrilla a fuego alto hasta que los bordes estén ligeramente dorados; aderece inmediatamente con vinagre, aceite de oliva, limón, orégano, ajo y perejil.</p>",
