    "recipe_fr": "<p>Faire mijoter le poulpe avec du laurier jusqu'à ce qu'il soit tendre ; égoutter, laisser refroidir et séparer les tentacules ; griller à feu vif jusqu'à ce qu'ils soient noircis sur les bords ; assaisonner immédiatement avec du vinaigre, de l'huile d'olive, du citron, de l'origan, de l'ail et du persil.</p>",
