    "recipe": "<p>Постави затворените миди директно върху горещата решетка и ги печи, докато се отворят</p><p>Отстрани горната половина на всяка черупка и изхвърли неотворените миди</p><p>Смеси маслото, чесъна, галетата, магданоза и лимоновата кора и разпредели върху месото</p><p>Върни половинките върху грила за 3–4 минути до златиста, кипяща коричка</p>",
