    "recipe_en": "<p>Place the closed mussels directly on the hot grill grate and cook until they open</p><p>Remove the top half of each shell and discard any mussels that stay closed</p><p>Mix butter, garlic, breadcrumbs, parsley and lemon zest and spoon over the meat</p><p>Return the half shells to the grill for 3 to 4 minutes until golden and bubbling</p>",
