    "ingredients_de": "1,2 kg Grünlippmuscheln || 80 g Butter || 4 Knoblauchzehen || 80 g Semmelbrösel || 25 g Petersilie || 1 Zitrone || 100 ml Weißwein || 1 Prise schwarzer Pfeffer",
    "recipe_de": "<p>Die geschlossenen Muscheln direkt auf den heißen Grillrost legen und grillen, bis sie sich öffnen.</p><p>Die obere Hälfte jeder Schale entfernen und alle geschlossenen Muscheln aussortieren.</p><p>Butter, Knoblauch, Semmelbrösel, Petersilie und Zitronenschale vermischen und über das Fleisch geben.</p><p>Die Muschelhälften für 3 bis 4 Minuten zurück auf den Grill legen, bis sie goldbraun und blubbernd sind.</p>",
