    "recipe_es": "<p>Coloca los mejillones cerrados directamente sobre la parrilla caliente y cocínalos hasta que se abran; retira la mitad superior de cada concha y desecha los mejillones que permanezcan cerrados; mezcla la mantequilla, el ajo, el pan rallado, el perejil y la ralladura de limón y vierte la mezcla sobre la carne; vuelve a colocar las medias conchas en la parrilla durante 3 o 4 minutos hasta que estén doradas y burbujeantes.</p>",
