    "ingredients_fr": "1,2 kg de moules vertes || 80 g de beurre || 4 gousses d’ail || 80 g de chapelure || 25 g de persil || 1 citron || 100 ml de vin blanc || 1 pincée de poivre noir",
    "recipe_fr": "<p>Déposez les moules fermées directement sur la grille chaude et faites-les cuire jusqu'à ce qu'elles s'ouvrent.</p><p>Retirez la moitié supérieure de chaque coquille et jetez les moules restées fermées.</p><p>Mélangez le beurre, l'ail, la chapelure, le persil et le zeste de citron, puis nappez-en les moules.</p><p>Remettez les demi-coquilles sur le gril pendant 3 à 4 minutes, jusqu'à ce qu'elles soient dorées et que le mélange bouillonne.</p>",
