    "recipe_ru": "<p>Положите закрытые мидии прямо на горячую решетку гриля и готовьте, пока они не откроются; снимите верхнюю половину каждой раковины и выбросьте все мидии, которые остались закрытыми; смешайте сливочное масло, чеснок, панировочные сухари, петрушку и лимонную цедру и полейте этой смесью мясо; верните половинки раковин на гриль на 3-4 минуты, пока они не подрумянятся и не начнут пузыриться.</p>",
